import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const b=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2022-11-23","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2022-11-23","date":"2022-11-23T00:00:00.000Z","updated":"2022-11-23T00:00:00.000Z","tags":["Ceph","RGW","Object Lambda","AWS","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-23.md","filePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-23.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-23.md"};function o(n,a,h,d,s,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-对象-lambda-object-lambda-的讨论与-rgw-改进" tabindex="-1">会议主题：对象 Lambda (Object Lambda) 的讨论与 RGW 改进 <a class="header-anchor" href="#会议主题-对象-lambda-object-lambda-的讨论与-rgw-改进" aria-label="Permalink to &quot;会议主题：对象 Lambda (Object Lambda) 的讨论与 RGW 改进&quot;">​</a></h4><h4 id="与会人员-ceph-研发团队成员" tabindex="-1">与会人员：Ceph 研发团队成员 <a class="header-anchor" href="#与会人员-ceph-研发团队成员" aria-label="Permalink to &quot;与会人员：Ceph 研发团队成员&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>对象 Lambda 与 AWS 对象 Lambda 的比较</strong></p><ul><li>讨论了对象 Lambda 与 AWS 对象 Lambda 的差异性，包括 AWS 对象 Lambda 支持多种语言并通过不同 URL 处理对象获取。</li><li>强调了大型对象处理中的性能和资源分配问题，建议考虑外部处理以减轻 RGW（RADOS Gateway）的性能压力。</li></ul></li><li><p><strong>处理方式的选择</strong></p><ul><li>探讨了内联处理与离线处理的优劣，以及在内线处理中数据匿名化等场景的必要性。</li><li>讨论了通过不同 URL 区分处理请求的可能性，以及实现该机制的方案。</li></ul></li><li><p><strong>技术方案的探索</strong></p><ul><li>分析了使用多站点方案的不可行性，并考虑使用外部服务来处理对象 Lambda。</li><li>探讨了与 IBM Fabric 技术的结合，以及利用现有的服务器less函数套件来增强功能。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>继续探索和评估外部处理方案，尤其是与 S3 接口兼容的方案。</li><li>考虑在 RGW 之外建立一个弹性计算设施，以实现更好的资源管理和扩展性。</li><li>讨论了与 Spark 和其他大数据生态系统的集成，以及优化数据处理和查询推送。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>进一步研究和测试外部处理方案，以确保最佳实践。</li><li>与 Ronancott 团队进行更深入的讨论，探索技术整合的可能性。</li><li>持续关注和评估与 Spark 和其他大数据工具的集成，以提高数据处理的效率和灵活性。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>安排与 Eric 的会议，讨论 aeroflight 技术的进一步开发和集成。</li><li>与 Ali 合作，探索 Spark 连接器的开发和优化。</li><li>评估和优化 S3 select 的功能，特别是在 Spark Catalyst 中的应用。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议重点讨论了对象 Lambda 的功能和实现，特别是在性能和资源管理方面的平衡。团队决定探索外部处理方案，并持续优化与大数据生态系统的集成。会议强调了持续研究和测试的重要性，以确保技术方案的有效性和可行性。</p><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>讨论 aeroflight 技术的进展和 Spark 集成方案。</li><li>评估 S3 select 在 Spark 中的应用和优化。</li></ul><p>感谢所有与会者的积极参与和宝贵意见，期待下次会议的进一步讨论。</p>',16)])])}const u=e(r,[["render",o]]);export{b as __pageData,u as default};
